import { useEffect, useState } from "react";
import { call, ApiError, type ProblemDetails } from "../../api/client.js";
import { loadMe, type Me } from "../login/me.js";

/* ════════════════════════════════════════════════════════════════════
   机构质控。

   ── 这一页存在的理由是一条制度，不是一张表 ────────────────────────
   **机构提出的事件，关闭权在机构。** 我方不能自行关闭 ——
   否则"已关闭"这三个字在核查时一文不值：
   被查的人自己说查完了，那不是质控，是台账整理。

   所以这一页是机构办**唯一有动作**的页面（角色一共就一个 closeQA），
   而质量台账那一页（我方的 /quality）是只读的同一批数据。
   同一本账，两边各自能动的部分不一样 —— 这正是要点。

   ── 关闭必须写整改说明 ────────────────────────────────────────────
   不是为了留痕好看：核查时真正被问的就是这一栏 ——
   "这件事你们是怎么处理的"。一句"已处理"等于没写，
   所以最短 4 个字（契约里的 WithReason），而页面上说清它会进审计轨迹。

   ── 为什么不做"新建事件" ──────────────────────────────────────────
   契约里没有对外开放的 raiseQualityEvent：事件要么由动作自动生成
   （访视超窗、SAE 超时），要么由我方人员提。
   机构现场发现的问题，眼下走的还是纸质质控报告 ——
   把一个"新建"按钮画在这里，点下去只会拿一个 404。
   缺这一块，写在页面上，不藏着。
   ════════════════════════════════════════════════════════════════════ */

interface Quality {
  id: string; code: string; siteCode: string; kind: string;
  severity: string; state: string; title: string; detail: string;
  autoGenerated: boolean; raisedBy: string; raisedOn: string; ageDays: number;
}

const KIND: Record<string, string> = {
  deviation: "方案偏离", query: "数据质疑", ip_discrepancy: "药品不平衡",
  sae: "严重不良事件", sae_late: "SAE 超时上报", other: "其他"
};
const SEV: Record<string, { label: string; chip: string }> = {
  minor: { label: "轻微", chip: "flat" },
  major: { label: "严重", chip: "warn" },
  critical: { label: "重大", chip: "crit" }
};
/* 取值就是契约里的 QUALITY_STATES 三个，不多不少。
   多写两个"调查中/整改中"看着更全，实际是把不存在的状态摆上台面 ——
   界面上出现过的状态，人就会问"怎么把它推到那一步"。 */
const STATE: Record<string, string> = {
  open: "待整改", pending_review: "待复核", closed: "已关闭"
};

export function InstQcPage() {
  const [me, setMe] = useState<Me | null>(null);
  const [items, setItems] = useState<Quality[] | null>(null);
  const [openOnly, setOpenOnly] = useState(true);
  const [closing, setClosing] = useState<string | null>(null);
  const [reason, setReason] = useState("");
  const [busy, setBusy] = useState(false);
  const [problem, setProblem] = useState<ProblemDetails | null>(null);
  const [said, setSaid] = useState<string | null>(null);

  const reload = () =>
    call<{ items: Quality[] }>("listQualityEvents", { query: { limit: 200 } })
      .then(r => setItems(r.items));

  useEffect(() => { void loadMe().then(setMe); void reload(); }, []);

  if (!me || !items) return <p className="muted">加载中…</p>;

  const canClose = me.permissions.actions.includes("closeQA");

  const close = async (q: Quality) => {
    setBusy(true); setProblem(null); setSaid(null);
    try {
      await call("closeQualityEvent", { params: { id: q.id }, body: { reason } });
      await reload();
      setClosing(null); setReason("");
      setSaid(`已关闭 ${q.code}`);
    } catch (e) {
      if (e instanceof ApiError) setProblem(e.problem); else throw e;
    } finally { setBusy(false); }
  };

  const open = items.filter(q => q.state !== "closed");
  const shown = (openOnly ? open : items)
    /* 重的排前面，同样重的按挂了多久排。
       **不按发现日排** —— 那样一件挂了 90 天的重大事件
       会被今天新提的几件轻微事件挤到下面去。 */
    .slice().sort((a, b) =>
      sevRank(b.severity) - sevRank(a.severity) || b.ageDays - a.ageDays);
  const stale = open.filter(q => q.ageDays > 30);

  return (
    <>
      <div className="page-head">
        <h2>机构质控</h2>
        <p data-testid="qc-summary">
          {open.length === 0
            ? "本院中心上没有未了结的质量事件。"
            : <>{open.length} 件未了结
                {stale.length > 0 && <>，其中 <b>{stale.length} 件挂了 30 天以上</b></>}。</>}
        </p>
      </div>

      <div className="derive" style={{ marginBottom: 14 }}>
        <b>机构提出的事件，关闭权在机构。</b> 我方不能自行关闭 ——
        否则「已关闭」这三个字在核查时一文不值：被查的人自己说查完了，
        那不是质控，是台账整理。
        <br />
        所以同一本账，我方那一页是<b>只读</b>的，这一页能动手。
      </div>

      {!canClose && (
        <p className="problem" data-testid="qc-forbidden">
          你的角色（{me.account.role.name}）没有「关闭质量事件」这个动作 ——
          下面这张表对你是只读的。
        </p>
      )}

      <label className="field" style={{ maxWidth: 280, marginBottom: 12 }}>
        <span>
          <input type="checkbox" checked={openOnly} data-testid="qc-open-only"
            onChange={e => setOpenOnly(e.target.checked)} />
          {" "}只看未了结的
        </span>
      </label>

      {problem && (
        <div className="problem stack" data-testid="qc-problem" style={{ marginBottom: 12 }}>
          <strong>{problem.title}</strong>
          {problem.detail && <div>{problem.detail}</div>}
        </div>
      )}
      {said && <p className="muted" data-testid="qc-said">{said}</p>}

      {shown.length === 0 ? (
        <p className="muted" data-testid="qc-empty">
          {openOnly
            ? <>没有未了结的。<b>这一页空着是好事</b> —— 去掉上面的勾可以看全部历史。</>
            : "本院中心上还没有质量事件记录。"}
        </p>
      ) : (
        <div className="table-wrap">
          <table>
            <thead>
              <tr>
                <th>编号</th><th>中心</th><th>类型</th><th>严重度</th>
                <th>事由</th><th>提出</th><th className="num">挂了</th>
                <th>状态</th><th />
              </tr>
            </thead>
            <tbody>
              {shown.map(q => (
                <tr key={q.id} data-testid="qc-row">
                  <td className="mono">{q.code}</td>
                  <td className="mono">{q.siteCode}</td>
                  <td>{KIND[q.kind] ?? q.kind}</td>
                  <td>
                    <span className={`chip ${SEV[q.severity]?.chip ?? "flat"}`}>
                      {SEV[q.severity]?.label ?? q.severity}
                    </span>
                  </td>
                  <td>
                    {q.title}
                    <div className="muted" style={{ fontSize: 12 }}>{q.detail}</div>
                  </td>
                  <td className="muted">
                    {/* 自动生成的那些是动作触发时**在同一个事务里**写的 ——
                        事后补录的记录，核查时看的是补录时间，不是发生时间。 */}
                    {q.autoGenerated ? "系统自动" : q.raisedBy}
                    <div className="mono" style={{ fontSize: 12 }}>{q.raisedOn}</div>
                  </td>
                  <td className="num">
                    {q.ageDays > 30 && q.state !== "closed"
                      ? <span className="chip warn" data-testid="qc-stale">{q.ageDays} 天</span>
                      : `${q.ageDays} 天`}
                  </td>
                  <td>{STATE[q.state] ?? q.state}</td>
                  <td>
                    {q.state === "closed"
                      ? <span className="muted">已了结</span>
                      : canClose
                        ? <button className="btn" data-testid={`qc-close-${q.id}`}
                            onClick={() => { setClosing(q.id); setReason(""); setProblem(null); }}>
                            关闭
                          </button>
                        : <span className="muted">不归你关</span>}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {closing && (() => {
        const q = items.find(x => x.id === closing);
        if (!q) return null;
        return (
          <div className="card stack" data-testid="qc-form" style={{ marginTop: 16 }}>
            <h3>关闭 <span className="mono">{q.code}</span> · {q.title}</h3>
            <label className="field">
              <span>整改说明（会写进审计轨迹）</span>
              <textarea rows={3} value={reason} data-testid="qc-reason"
                placeholder="做了什么、谁做的、什么时候做完的"
                onChange={e => setReason(e.target.value)} />
            </label>
            <p className="muted" style={{ margin: 0 }}>
              核查时真正被问的就是这一栏：<b>「这件事你们是怎么处理的」</b>。
              一句「已处理」等于没写。
            </p>
            <div className="row">
              <button className="btn primary" data-testid="qc-submit"
                disabled={busy || reason.trim().length < 4}
                onClick={() => void close(q)}>
                {busy ? "…" : "关闭这件事"}
              </button>
              <button className="btn" onClick={() => { setClosing(null); setReason(""); }}>
                取消
              </button>
            </div>
          </div>
        );
      })()}

      <div className="derive" style={{ marginTop: 14 }}>
        <b>这里没有「新建事件」。</b> 事件要么由动作自动生成
        （访视超窗、SAE 超过 24 小时未报），要么由我方人员提出 ——
        机构现场发现的问题目前还走纸质质控报告。
        画一个点下去只会报错的按钮，比缺这一块更糟，所以缺在这里说明。
      </div>
    </>
  );
}

const sevRank = (s: string) => ({ critical: 3, major: 2, minor: 1 } as Record<string, number>)[s] ?? 0;
